def simulate_stones(N, A):
    stones = A[:]
    for _ in range(N):
        for i in range(1, N):
            if stones[i] >= 1:
                stones[i - 1] += 1
                stones[i] -= 1
    return stones

# Example usage
N = int(input())
stones = list(map(int, input().split()))
print(' '.join(map(str, simulate_stones(N, stones))))

