class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        counter = Counter(nums)
        freq_map = defaultdict(int)
        max_freq = 0

        for num, count in counter.items():
            if num + k not in freq_map:
                freq_map[num + k] = 0
            freq_map[num + k] += count

            while sum(freq_map.values()) > k:
                left_num = list(freq_map.keys())[0]
                freq_map[left_num] -= counter[left_num]
                if freq_map[left_num] == 0:
                    del freq_map[left_num]

            max_freq = max(max_freq, len(freq_map))

        return max_freq

def check_full_house(cards):
    # Count occurrences of each number
    counts = {}
    for card in cards:
        if card in counts:
            counts[card] += 1
        else:
            counts[card] = 1

    # Check for exactly two numbers with count 3 and one number with count 2
    return any(count == 3 for count in counts.values()) and sum(count == 2 for count in counts.values()) == 1

