def is_colorful_bracket_sequence(s):
    stack = []

    for char in s:
        if char in '([{':
            stack.append(char)
        elif char == ')':
            if not stack or stack[-1] != '(':
                return False
            stack.pop()
        elif char == ']':
            if not stack or stack[-1] != '[':
                return False
            stack.pop()
        elif char == '>':
            if not stack or stack[-1] != '<':
                return False
            stack.pop()

    return len(stack) == 0

