def is_colorful_bracket_sequence(S):
    stack = []
    for char in S:
        if char == '(' or char == '[' or char == '<':
            stack.append(char)
        elif char == ')' and stack and stack[-1] == '(':
            stack.pop()
        elif char == ']' and stack and stack[-1] == '[':
            stack.pop()
        elif char == '>' and stack and stack[-1] == '<':
            stack.pop()
        else:
            return "No"
    return "Yes" if not stack else "No"

