class Solution:
    def maxWeight(self, pizzas: List[int]) -> int:
        # Initialize variables
        n = len(pizzas)
        dp = [[0 for _ in range(n // 4)] for _ in range(n)]

        # Base case: on the first day, we can eat any 4 pizzas
        for i in range(4):
            dp[0][i] = sum(pizzas[:i+1])

        # Fill the DP table
        for day in range(1, n // 2):
            for start in range(n - 3, -1, -4):
                end = start + 3
                if end >= n:
                    break

                # Calculate the maximum weight gain on this day
                for k in range(start, end + 1):
                    if k % 2 == 0:
                        dp[day][start] = max(dp[day][start], dp[day-1][k] + pizzas[k])
                    else:
                        dp[day][start] = max(dp[day][start], dp[day-1][k] + pizzas[k] + pizzas[end])

                # If it's an odd number of days, add the weight of the last pizza
                if day % 2 != 0:
                    dp[day][start] += pizzas[end]

        # The answer is the maximum weight gain on the last day
        return dp[-1][0]

class Solution:
    def reverseDegree(self, s: str) -> int:
        reverse_alphabet = {chr(i): i for i in range(97, 123)}
        result = 0

        for index, char in enumerate(s):
            result += reverse_alphabet[char] * (index + 1)

        return result

class Solution:
    def reverseDegree(self, s: str) -> int:
        # Calculate the reversed index of each letter in the alphabet
        reversed_index_map = {char: idx + 1 for idx, char in enumerate(reversed('abcdefghijklmnopqrstuvwxyz'))}

        # Initialize the result variable
        result = 0

        # Iterate over each character in the input string
        for i, char in enumerate(s):
            # Get the reversed index of the current character
            reversed_idx = reversed_index_map[char]

            # Add the product of the reversed index and the current index to the result
            result += reversed_idx * (i + 1)

        return result

class Solution:
    def maxContainers(self, n: int, w: int, maxWeight: int) -> int:
        count = 0
        current_weight = 0

        for i in range(n):
            for j in range(n):
                if current_weight + w > maxWeight:
                    break
                current_weight += w
                count += 1

        return count

