class Solution:
    def minCost(self, nums: List[int]) -> int:
        if len(nums) == 0:
            return 0

        nums.sort()

        total_cost = 0
        i = 0
        while i < len(nums):
            if i+2 < len(nums):
                total_cost += max(nums[i], nums[i+1])
                i += 3
            else:
                total_cost += max(nums[i:])
                break

        return total_cost

