class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        ans = [-1]*len(groups)
        d = defaultdict(list)
        for i in range(len(elements)):
            d[elements[i]].append(i)

        for i in range(len(groups)):
            for e in groups[i]:
                if e in d:
                    ans[i] = min(d[e])
                    break

        return ans

