class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        ans = [-1]*len(groups)
        for i in range(len(elements)):
            for j in range(len(groups)):
                if groups[j] % elements[i] == 0:
                    if ans[j] == -1:
                        ans[j] = i
                    else:
                        if i < ans[j]:
                            ans[j] = i
        return ans

