class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        parent = list(range(len(properties)))
        size = [1]*len(properties)

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x,y):
            root_x = find(x)
            root_y = find(y)

            if root_x == root_y:
                return

            if size[root_x] > size[root_y]:
                root_x, root_y = root_y, root_x

            parent[root_y] = root_x
            size[root_x] += size[root_y]

        for prop in properties:
            for other_prop in properties:
                if prop != other_prop and intersect(prop,other_prop)>=k:
                    union(prop[0],other_prop[0])

        return len(set(find(i) for i in range(len(properties))))

