import collections

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        graph = collections.defaultdict(set)

        for i, prop1 in enumerate(properties):
            for j, prop2 in enumerate(properties):
                if i != j and self.intersect(prop1, prop2) >= k:
                    graph[i].add(j)
                    graph[j].add(i)

        visited = set()
        count = 0

        for node in range(len(properties)):
            if node not in visited:
                self.dfs(graph, node, visited)
                count += 1

        return count

    def dfs(self, graph, node, visited):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                self.dfs(graph, neighbor, visited)

    def intersect(self, prop1, prop2):
        return len(set(prop1).intersection(set(prop2)))
